from edit_registry import ROOT,WORK,apply
from pathlib import Path
main=(ROOT/'manuscript/BMEF_main.tex').read_text()
def paragraph(prefix):return next(l for l in main.splitlines() if l.startswith(prefix))
evidence=['reports/revision_evidence_night_20261102/G2/REPORT.md','reports/adni_image_acquisition_audit/filtering_code_recovery_20261103/REPORT.md','reports/adni_image_acquisition_audit/metadata_1103_review/REPORT.md']
old=paragraph('This study leveraged neuroimaging data')
new=old+' Only one prepared imaging record per participant was retained; repeated longitudinal visits were not treated as independent participants. The recovered clinical-record selection rule took the first CSV record matching each participant, which should not be interpreted as a nearest-date MRI--PET pairing rule. The actual acquisition identifiers and maximum MRI--PET interval could not be established for the complete imaging cohort; the recovered clinical-source Image IDs do not resolve that file-level correspondence.'
apply('G2-COHORT-SELECTION','manuscript/BMEF_main.tex',old,new,['R2-6','R3-6','R2-19'],['G2','G8'],evidence,'Preserve subject-level author protocol and clarify recovered clinical selection versus unverified actual acquisition identity',section='Materials and Data Preprocessing / cohort')
old=paragraph('Participants were stratified into five')
new=old.replace('indicated proximity to dementia conversion','denoted a more severe impairment stage').replace('without clear progression status','not classified as EMCI or LMCI').replace('This granular stratification facilitates a biologically grounded analysis of neuroanatomical and metabolic alterations across the AD spectrum, thereby enhancing the clinical validity of synthesized PET images.','These categories define cross-sectional diagnostic and MCI-stage comparisons, without establishing longitudinal prognosis.')
apply('G2-MCI-DEFINITIONS','manuscript/BMEF_main.tex',old,new,['R2-4','R3-3','R3-6'],['G2','G7'],['rebuttal/BMEF_from_notion/BMEF审稿回复/R3-3正文修改 51895d43b2dd838dbc088101b7eab8e2.md'],'Merge confirmed stage definitions; remove conversion/progression assumptions',section='Materials and Data Preprocessing / diagnostic groups')
old=paragraph('To further validate the generalizability')
new=r'''External evaluation used the Open Access Series of Imaging Studies (OASIS-3), a longitudinal neuroimaging and clinical cohort focused on normal aging and Alzheimer's disease (\url{https://www.oasis-brains.org}). The retained external cohort comprised 419 participants with AV45-PET processed using the Pet Unified Pipeline (PUP): 334 CN and 85 AD, with no MCI participants (Table~\ref{tab:supp_oasis}). FDG-PET from the smaller subset ($n=117$) was excluded because it lacked the PUP processing used for this external cohort. Subsequent model inputs were min--max normalized; the external evaluation does not establish clinical SUV/SUVR calibration. The CN and AD groups differed in age distribution. These data therefore evaluate external AV45 synthesis in this CN/AD cohort, without establishing external generalizability for FDG synthesis or MCI-stage discrimination. Complete run-specific records of the external clinical prompt fields and missing-field handling were not retained, limiting reproducibility of that historical evaluation.'''
apply('G2-OASIS-SCOPE','manuscript/BMEF_main.tex',old,new,['R2-7','R3-13','R3-6'],['G2','G7'],['rebuttal/BMEF_from_notion/BMEF审稿回复/R3-13正文修改 40d95d43b2dd80d48434d6591b4e6c4e.md','manuscript/supplementary/supplementary.tex'],'Merge cohort counts and normalization scope; explicitly preserve unresolved external prompt provenance',section='Materials and Data Preprocessing / OASIS')
old=paragraph('To ensure precise spatial correspondence')
new=old.replace('brain parenchyma was parcellated into 98 anatomical structures using SynthSeg~\\cite{synthseg}.','T1-weighted MRI scans were parcellated into 98 anatomical regions using SynthSeg~\\cite{synthseg}, and the resulting ROI masks were applied to the spatially aligned PET images.')
new += ' ADNI provided preprocessed PET images upstream of this pipeline. Spatial registration and intensity normalization do not establish comprehensive scanner-specific harmonization; acquisition and upstream processing details could not be verified for every actual model input.'
apply('G2-PREPROCESSING','manuscript/BMEF_main.tex',old,new,['R3-6','M7','M12'],['G2','G4'],evidence+['rebuttal/BMEF_from_notion/BMEF审稿回复/M7正文修改 40795d43b2dd8025b837db224bcb3515.md'],'Merge MRI-based SynthSeg masking with bounded acquisition/scanner provenance; bibliography corrections follow separately',section='Materials and Data Preprocessing / preprocessing')
old=paragraph('Model evaluation was conducted under a two-fold')
new=r'''PET synthesis used subject-level two-fold cross-validation with fixed, approximately equal partitions (929 and 928 participants; split seed 42). In each fold, training and held-out participants were disjoint. Held-out predictions from the two folds were combined into an out-of-fold (OOF) dataset for generation analyses, with 1,598 valid FDG and 1,365 valid AV45 observations before the separately specified MRI/mask QC exclusion used in masked evaluation. Downstream classification used a separate task-specific stratified three-fold protocol, described below. The classification analysis retained the existing author-provided synthetic PET dataset under the intended two-fold OOF design; its image-to-checkpoint correspondence to the reconstructed Full generation experiments could not be independently established. Classification results are therefore reported as a separate input-asset analysis, rather than a downstream test of those reconstructed generator comparisons. Fixed splits, seeds and implementation details are summarized in Table~\ref{tab:reproducibility}.'''
apply('G2-OOF-PROTOCOL','manuscript/BMEF_main.tex',old,new,['R2-3','R2-6','R2-19','R3-6','R3-7','R3-13'],['G2','G5'],evidence+['reports/r2_11_classification_3fold/final_summary/REPORT.md'],'Merge protocol statements while retaining bounded checkpoint-identity limitation documented by G2',section='Materials and Data Preprocessing / evaluation split')
old=paragraph('The data used in this study were obtained from two publicly')
new=r'''The data used in this study were obtained from two research datasets: the Alzheimer's Disease Neuroimaging Initiative (ADNI) and the Open Access Series of Imaging Studies (OASIS-3). ADNI data are available to approved researchers through the LONI Image and Data Archive (IDA) at \url{https://ida.loni.usc.edu}, subject to the ADNI Data Use Agreement. OASIS-3 data are available through the official OASIS data access process at \url{https://sites.wustl.edu/oasisbrains/request-access/}, subject to the corresponding data use terms. ADNI inputs included T1-weighted MRI, $^{18}$F-FDG PET, $^{18}$F-AV45 PET, and demographic and clinical assessments; external OASIS-3 evaluation used MRI and AV45-PET. Fixed subject-level split records and source manifests for the revised analyses were retained. Sharing of subject- and image-level identifiers is subject to the applicable data access and redistribution requirements. Clinical-source identifiers must not be interpreted as verified acquisition identifiers of the actual model inputs.'''
apply('G2-DATA-AVAILABILITY','manuscript/BMEF_main.tex',old,new,['M15','R2-19','R3-6'],['G2'],['rebuttal/BMEF_from_notion/BMEF审稿回复 3d295d43b2dd8300b74601d792205677.md',*evidence],'Apply confirmed M15 scope and avoid unsupported blanket Creative Commons claim',section='Data Availability')
supp=(ROOT/'manuscript/supplementary/supplementary.tex').read_text();old=next(l for l in supp.splitlines() if l.startswith('To obtain the required text-guided information'))
new=r'''The historical OASIS-3 external cohort comprised 419 PUP-processed AV45 participants (334 CN, 85 AD); the 117 FDG participants without the corresponding processing were not included. The age distributions differed between diagnostic groups (Table~\ref{tab:supp_oasis}). Reported clinical summaries do not establish which complete prompt fields were used in every external run or how unavailable fields were handled. The external results are restricted to AV45 synthesis in CN/AD and do not provide FDG or MCI external evidence.'''
apply('G2-SUPP-OASIS','manuscript/supplementary/supplementary.tex',old,new,['R3-13','R2-7','M21'],['G2','G7'],evidence,'Align supplementary selection description with actual retained scope and unresolved prompt handling',section='OASIS cohort description')
tex=r'''\begin{table}[htbp]
\caption{\textbf{Reproducibility settings and scope of the revised analyses.}}
\label{tab:reproducibility}
\centering\small
\begin{tabularx}{\textwidth}{p{0.25\textwidth}X}
\toprule
Component & Recorded settings and limitations \\
\midrule
Reconstructed generation & 1,857 subjects; fixed two-fold partitions of 929/928, split seed 42. Full, TracerOnly, TabularMLP and Single did not use a fixed training seed; deterministic repeated-training behavior is not claimed. Epoch 165 is the principal comparison endpoint; MRI-only Swin-UNETR uses its prespecified epoch 200. \\
Classification & Task-specific subject-level stratified three-fold splits (seed 42); 15\% stratified internal validation within each outer training fold. Fit seed $42+100\times\mathrm{task\ index}+\mathrm{fold}$, with task index AD/CN=0, MCI/CN=1, EMCI/LMCI=2 and folds 1--3. Training lasts 200 epochs with validation every two epochs; checkpoint selected by validation ACC; outer test evaluated once after reloading. \\
Classification cohorts & AD/CN: 470 (165 AD, 305 CN); MCI/CN: 741 (436 EMCI+LMCI, 305 CN); EMCI/LMCI: 436 (287 EMCI, 149 LMCI). MCI-U excluded. The task-specific partitions are shared across input conditions. \\
Source identity & The historical classification Syn-PET inputs are distinct from the reconstructed generation comparisons; a direct checkpoint binding between these image families was not established. Existing classification inputs were not regenerated. \\
Clinical source & Clinical rows selected by first CSV record per participant; five score fields contain diagnosis-conditioned fills. Original filling random states and complete actual acquisition mappings were not recovered. \\
\bottomrule
\end{tabularx}
\end{table}
'''
q=ROOT/'manuscript/supplementary/tables/reproducibility.tex';assert not q.exists();q.write_text(tex)
p=ROOT/'manuscript/supplementary/supplementary.tex';anchor=r'\input{supplementary/tables/clinical_missingness}'
apply('G2-REPRODUCIBILITY-INPUT','manuscript/supplementary/supplementary.tex',anchor,anchor+'\n'+r'\input{supplementary/tables/reproducibility}',['R2-19','R2-3','R3-6'],['G2','G5'],evidence,'Add recorded settings by experiment family, without claiming exact recovery of all historical runs',section='tab:reproducibility')
